use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};
use crate::aap::caps::types::Intent;

/// Precondition from the node contract: len(question) <= 512.
const MAX_QUESTION_LEN: usize = 512;
/// Bounded tool-orchestration loop: at most this many model rounds.
const MAX_ROUNDS: usize = 3;

const SYSTEM: &str = "Answer the customer's question using only the provided knowledge. \
To search the knowledge base, request the 'lookup' tool with a query.";

struct Node;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

fn fail(message: &str) -> ResponseResult {
    ResponseResult::Error(LlmError {
        message: message.to_string(),
    })
}

fn render_knowledge(items: &[String]) -> String {
    if items.is_empty() {
        return String::from("(none)");
    }
    items
        .iter()
        .map(|s| format!("- {s}"))
        .collect::<Vec<_>>()
        .join("\n")
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        if ctx.question.len() > MAX_QUESTION_LEN {
            return fail("question exceeds 512 bytes");
        }

        // One knowledge-base read, scoped to the question, merged with the
        // knowledge already attached to the context.
        let mut knowledge = ctx.knowledge.clone();
        knowledge.extend(kb_read::lookup(&ctx.question));

        let mut prompt = format!(
            "Intent: {}\nQuestion: {}\nKnowledge:\n{}",
            intent_label(ctx.intent),
            ctx.question,
            render_knowledge(&knowledge),
        );

        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(SYSTEM, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool != "lookup" {
                        return fail("requested tool is outside this node's scope");
                    }
                    if req.query.len() > MAX_QUESTION_LEN {
                        return fail("lookup query exceeds 512 bytes");
                    }
                    let found = kb_read::lookup(&req.query);
                    prompt.push_str("\nLookup query: ");
                    prompt.push_str(&req.query);
                    prompt.push_str("\nLookup results:\n");
                    prompt.push_str(&render_knowledge(&found));
                }
            }
        }

        fail("tool-call budget exhausted without a final answer")
    }
}

export!(Node);
